# Gera sql/modulo2.sql: aulas e atividades do Módulo 2 (Visão Celular).
# Uso: python3 sql/gerar_modulo2.py > sql/modulo2.sql
import json

MODULO = 2
ID_BASE = 10  # aulas do Módulo 1 usam ids 1..10; Módulo 2 usa 11..19


def U(enun, opcoes, certa, expl):
    return dict(tipo='unica', enunciado=enun,
                dados={'opcoes': [{'id': chr(97 + i), 'texto': t} for i, t in enumerate(opcoes)]},
                gabarito=certa, explicacao=expl)


def M(enun, opcoes, certas, expl):
    return dict(tipo='multipla', enunciado=enun,
                dados={'opcoes': [{'id': chr(97 + i), 'texto': t} for i, t in enumerate(opcoes)]},
                gabarito=certas, explicacao=expl)


def L(enun, partes, gab, expl):
    return dict(tipo='lacunas', enunciado=enun, dados={'partes': partes}, gabarito=gab, explicacao=expl)


def A(enun, ref):
    return dict(tipo='aberta', enunciado=enun, dados={}, gabarito={'referencia': ref}, explicacao=None)


def S(titulo, texto=None, itens=None, ref=None):
    s = {'titulo': titulo}
    if texto: s['texto'] = texto
    if itens: s['itens'] = itens
    if ref: s['ref'] = ref
    return s


