dict(titulo='Preparando-se para Enviar',
 versiculo='Ide, portanto, fazei discípulos de todas as nações, batizando-os em nome do Pai, do Filho e do Espírito Santo; ensinando-os a guardar todas as coisas que vos tenho ordenado.',
 versiculo_ref='Mateus 28:19-20',
 conteudo=[
  S('Introdução', 'Não podemos falar de enviar alguém sem compreender todo o processo: ganhar, consolidar e treinar, para então enviar. O que gera um líder pronto para ser enviado é o processo, e não o comissionamento. Não basta escolher uma pessoa cheia de qualidades e enviá-la a uma missão para a qual não está pronta.'),
  S('1. Entendendo os passos da Visão', 'O enviar é consequência de todo o processo da Visão. Os passos formam uma unidade funcional: um não funciona sem o outro.'),
  S('1.1 Ninguém é enviado sem que primeiro seja ganho', 'Ganhamos vidas já pensando em prepará-las para o seu papel profético-sacerdotal: anunciar o Evangelho. Não ganhamos pessoas para uma estatística. Deus nos amou; por isso amamos as pessoas, com paciência no processo de cada uma, ganhando-as pelo testemunho pessoal e despertando nelas o desejo de serem como Jesus (Jo 14:6).'),
  S('1.2 Somente alguém consolidado suporta o treinamento', 'A consolidação (Fp 4:10-13) é, primeiro, parte da metodologia da Visão: levar o novo convertido do pré-encontro ao pós-encontro e matriculá-lo na Escola de Líderes. Segundo, é o acompanhamento pessoal até a maturidade cristã. Trabalhamos para gerar filhos espirituais que saibam agir com autonomia, responsabilidade, respeito, santidade e temor a Deus.'),
  S('1.3 Recebendo treinamento para prosperar na Visão', 'Treinar é municiar: dar ao soldado as armas com as quais poderá lutar sem ser destruído e ensiná-lo a usá-las. Na batalha espiritual, nossas armas não são carnais, mas espirituais em Cristo Jesus.'),
  S('2. O que é preciso para ser enviado?',
    itens=['HUMILDADE – reconhecer que precisamos de libertação e cura, como Isaías: “Ai de mim!” — e depois responder: “Eis-me aqui” (Is 6)',
           'HONESTIDADE – portar-se com transparência diante dos homens, pois diante de Deus nada pode ser escondido',
           'RENÚNCIA – renunciar à velha natureza: Moisés tirou as sandálias (Êx 3:5) para calçar as sandálias do evangelho da paz (Ef 6:15)']),
  S('Conclusão', 'Precisamos estabelecer uma base sólida para que o enviar produza efeito. A Palavra de Deus nos mostra vários exemplos de envio com sucesso; seguindo esses princípios com cuidado, teremos êxito na tarefa.'),
 ],
 questoes=[
  U('Por que ninguém é enviado sem que primeiro seja ganho?',
    ['Porque o enviar é consequência de todo o processo da Visão: ganhamos as vidas já para prepará-las para o seu papel de anunciadoras do Evangelho.',
     'Porque é preciso ter muitos membros para fazer estatística.', 'Porque só pastores podem ser enviados.',
     'Não é necessário ser ganho para ser enviado.'], 'a', 'Itens 1 e 1.1.'),
  U('Como podemos suportar o treinamento?',
    ['Com força de vontade própria, sem ajuda.',
     'Sendo consolidados: levados do pré-encontro ao pós-encontro e à Escola de Líderes, e acompanhados até a maturidade cristã.',
     'Faltando às aulas mais difíceis.', 'Pulando direto para o envio.'], 'b', 'Item 1.2: somente alguém consolidado suporta o treinamento (Fp 4:10-13).'),
  U('Como prosperar na Visão?',
    ['Recebendo treinamento: sendo municiado com armas espirituais e aprendendo a usá-las.',
     'Usando armas carnais nas batalhas.', 'Trabalhando sozinho, sem líder.', 'Esperando que tudo aconteça sem preparo.'], 'a',
    'Item 1.3.'),
  M('O que é preciso para ser enviado? Marque as corretas.',
    ['Humildade', 'Fama', 'Honestidade', 'Dinheiro', 'Renúncia'], ['a', 'c', 'e'],
    'Item 2: Humildade (Is 6), Honestidade e Renúncia (Êx 3:5; Ef 6:15).'),
 ]),
