def lit(v):
    return "$j$" + json.dumps(v, ensure_ascii=False) + "$j$::jsonb"


def txt(s):
    return 'null' if s is None else "$t$" + s + "$t$"


out = ['-- Módulo 2 · Visão Celular (gerado por gerar_modulo2.py)', 'begin;']
for n, a in enumerate(AULAS, 1):
    aid = ID_BASE + n
    out.append(f"insert into public.escola_aulas(id, modulo, numero, titulo, versiculo, versiculo_ref, conteudo) values "
               f"({aid}, {MODULO}, {n}, {txt(a['titulo'])}, {txt(a['versiculo'])}, {txt(a['versiculo_ref'])}, {lit(a['conteudo'])}) "
               f"on conflict (id) do update set modulo=excluded.modulo, numero=excluded.numero, titulo=excluded.titulo, "
               f"versiculo=excluded.versiculo, versiculo_ref=excluded.versiculo_ref, conteudo=excluded.conteudo;")
    out.append(f"delete from public.escola_questoes q where q.aula_id = {aid} and not exists (select 1 from public.escola_entregas e where e.aula_id = {aid});")
    for o, q in enumerate(a['questoes'], 1):
        if q['tipo'] in ('unica', 'multipla'):
            ids = [x['id'] for x in q['dados']['opcoes']]
            for g in ([q['gabarito']] if q['tipo'] == 'unica' else q['gabarito']):
                assert g in ids, (a['titulo'], q['enunciado'])
        if q['tipo'] == 'lacunas':
            assert q['dados']['partes'].count(None) == len(q['gabarito']), q['enunciado']
        out.append(f"insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values "
                   f"({aid}, {o}, '{q['tipo']}', {txt(q['enunciado'])}, {lit(q['dados'])}, {lit(q['gabarito'])}, {txt(q['explicacao'])}, 1) "
                   f"on conflict (aula_id, ordem) do nothing;")
out.append('commit;')
print('\n'.join(out))
